const fs = require('fs');
const crypto = require('crypto');

console.log("1. Main Thread Starts (Waiter takes order)");

// We ask the Event Loop to do heavy math.
// It offloads this to the libuv C++ Thread Pool.
crypto.pbkdf2('password', 'salt', 100000, 64, 'sha512', () => {
  console.log("4. Heavy Math Finished! (Kitchen rings bell)");
});

// We set a timer.
setTimeout(() => {
  console.log("3. Timer Finished! (Kitchen rings bell)");
}, 100);

console.log("2. Main Thread continues working instantly! (Waiter goes to next table)");

// OUTPUT ORDER:
// 1. Main Thread Starts
// 2. Main Thread continues working
// 3. Timer Finished!
// 4. Heavy Math Finished!
